p_page_template','default'),(988,131,'_elementor_page_settings','a:1:{s:18:\"eael_ext_toc_title\";s:17:\"Table of Contents\";}'),(1003,132,'_edit_lock','1781462774:1'),(1005,132,'_eb_attr',''),(1006,132,'footnotes',''),(1007,132,'_elementor_edit_mode','builder'),(1008,132,'_elementor_template_type','wp-page'),(1009,132,'_elementor_data','[{\"id\":\"4103f0d\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"22468aa\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!-- HUMAN BODY EXPLORER - COMPLETE HOMEPAGE -->\\r\\n<style>\\r\\n\\/* ========== RESET & BASE ========== *\\/\\r\\n* { margin: 0; padding: 0; box-sizing: border-box; }\\r\\nbody {\\r\\n  font-family: \'Segoe UI\', system-ui, -apple-system, sans-serif;\\r\\n  background: #f5f7fa;\\r\\n  color: #1a1a2e;\\r\\n  transition: background 0.3s, color 0.3s;\\r\\n  overflow-x: hidden;\\r\\n}\\r\\nbody.dark-mode {\\r\\n  background: #0a0a1a;\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n\\/* ========== HERO SECTION ========== *\\/\\r\\n.hero {\\r\\n  min-height: 90vh;\\r\\n  display: flex;\\r\\n  flex-direction: column;\\r\\n  align-items: center;\\r\\n  justify-content: center;\\r\\n  text-align: center;\\r\\n  padding: 2rem 1rem;\\r\\n  background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);\\r\\n  position: relative;\\r\\n  overflow: hidden;\\r\\n}\\r\\n.hero::before {\\r\\n  content: \'\';\\r\\n  position: absolute;\\r\\n  top: -50%;\\r\\n  left: -50%;\\r\\n  width: 200%;\\r\\n  height: 200%;\\r\\n  background: radial-gradient(circle, rgba(255,255,255,0.1) 1px, transparent 1px);\\r\\n  background-size: 30px 30px;\\r\\n  animation: drift 20s linear infinite;\\r\\n}\\r\\n@keyframes drift {\\r\\n  from { transform: translate(0, 0); }\\r\\n  to { transform: translate(30px, 30px); }\\r\\n}\\r\\n.hero h1 {\\r\\n  font-size: clamp(2.5rem, 8vw, 4.5rem);\\r\\n  color: #fff;\\r\\n  text-shadow: 0 0 20px rgba(233,69,96,0.5);\\r\\n  margin-bottom: 1rem;\\r\\n  position: relative;\\r\\n  z-index: 1;\\r\\n}\\r\\n.hero p {\\r\\n  color: #ddd;\\r\\n  font-size: 1.2rem;\\r\\n  max-width: 700px;\\r\\n  margin: 0 auto 2rem;\\r\\n  position: relative;\\r\\n  z-index: 1;\\r\\n}\\r\\n.search-container {\\r\\n  width: 100%;\\r\\n  max-width: 500px;\\r\\n  position: relative;\\r\\n  z-index: 1;\\r\\n  margin-bottom: 2rem;\\r\\n}\\r\\n.search-container input {\\r\\n  width: 100%;\\r\\n  padding: 1rem 1.5rem;\\r\\n  border: none;\\r\\n  border-radius: 50px;\\r\\n  font-size: 1rem;\\r\\n  background: rgba(255,255,255,0.15);\\r\\n  backdrop-filter: blur(10px);\\r\\n  color: #fff;\\r\\n  outline: none;\\r\\n  border: 1px solid rgba(255,255,255,0.3);\\r\\n  transition: 0.3s;\\r\\n}\\r\\n.search-container input::placeholder { color: #ccc; }\\r\\n.search-container input:focus {\\r\\n  background: rgba(255,255,255,0.25);\\r\\n  border-color: #e94560;\\r\\n}\\r\\n.hero-buttons {\\r\\n  display: flex;\\r\\n  gap: 1rem;\\r\\n  flex-wrap: wrap;\\r\\n  justify-content: center;\\r\\n  position: relative;\\r\\n  z-index: 1;\\r\\n}\\r\\n.btn {\\r\\n  padding: 0.8rem 2rem;\\r\\n  border-radius: 50px;\\r\\n  font-weight: 600;\\r\\n  text-decoration: none;\\r\\n  transition: transform 0.3s, box-shadow 0.3s;\\r\\n  cursor: pointer;\\r\\n  border: none;\\r\\n  font-size: 1rem;\\r\\n}\\r\\n.btn-primary {\\r\\n  background: #e94560;\\r\\n  color: #fff;\\r\\n}\\r\\n.btn-primary:hover { transform: translateY(-3px); box-shadow: 0 10px 20px rgba(233,69,96,0.4); }\\r\\n.btn-secondary {\\r\\n  background: transparent;\\r\\n  border: 2px solid #fff;\\r\\n  color: #fff;\\r\\n}\\r\\n.btn-secondary:hover { background: #fff; color: #1a1a2e; }\\r\\n\\r\\n\\/* ========== STATS SECTION ========== *\\/\\r\\n.stats {\\r\\n  display: flex;\\r\\n  justify-content: center;\\r\\n  gap: 2rem;\\r\\n  flex-wrap: wrap;\\r\\n  padding: 2rem 1rem;\\r\\n  background: #16213e;\\r\\n}\\r\\n.stat-item {\\r\\n  text-align: center;\\r\\n  color: #fff;\\r\\n}\\r\\n.stat-number {\\r\\n  font-size: 2.5rem;\\r\\n  font-weight: 700;\\r\\n  color: #e94560;\\r\\n}\\r\\n.stat-label { font-size: 1rem; color: #ccc; }\\r\\n\\r\\n\\/* ========== SYSTEMS GRID ========== *\\/\\r\\n.systems-section {\\r\\n  padding: 4rem 2rem;\\r\\n  background: inherit;\\r\\n}\\r\\n.systems-section h2 {\\r\\n  text-align: center;\\r\\n  margin-bottom: 2rem;\\r\\n  font-size: 2rem;\\r\\n  color: inherit;\\r\\n}\\r\\n.systems-grid {\\r\\n  display: grid;\\r\\n  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\\r\\n  gap: 1.5rem;\\r\\n  max-width: 1200px;\\r\\n  margin: 0 auto;\\r\\n}\\r\\n.system-card {\\r\\n  background: rgba(255,255,255,0.08);\\r\\n  backdrop-filter: blur(12px);\\r\\n  border-radius: 20px;\\r\\n  padding: 2rem 1.5rem;\\r\\n  text-align: center;\\r\\n  border: 1px solid rgba(255,255,255,0.2);\\r\\n  transition: transform 0.3s, box-shadow 0.3s;\\r\\n  cursor: pointer;\\r\\n  color: inherit;\\r\\n  text-decoration: none;\\r\\n  display: block;\\r\\n}\\r\\n.system-card:hover {\\r\\n  transform: translateY(-8px);\\r\\n  box-shadow: 0 20px 40px rgba(0,0,0,0.3);\\r\\n}\\r\\n.system-icon {\\r\\n  font-size: 3rem;\\r\\n  margin-bottom: 1rem;\\r\\n}\\r\\n.system-card h3 {\\r\\n  font-size: 1.3rem;\\r\\n  margin-bottom: 0.5rem;\\r\\n}\\r\\n.system-card p {\\r\\n  font-size: 0.9rem;\\r\\n  opacity: 0.8;\\r\\n}\\r\\n\\r\\n\\/* ========== DAILY FEATURES ========== *\\/\\r\\n.daily-features {\\r\\n  display: flex;\\r\\n  flex-wrap: wrap;\\r\\n  gap: 2rem;\\r\\n  justify-content: center;\\r\\n  padding: 3rem 1rem;\\r\\n  max-width: 1200px;\\r\\n  margin: 0 auto;\\r\\n}\\r\\n.feature-card {\\r\\n  flex: 1 1 300px;\\r\\n  background: rgba(255,255,255,0.1);\\r\\n  backdrop-filter: blur(10px);\\r\\n  border-radius: 20px;\\r\\n  padding: 2rem;\\r\\n  border: 1px solid rgba(255,255,255,0.2);\\r\\n}\\r\\n.feature-card h3 { margin-bottom: 1rem; display: flex; align-items: center; gap: 0.5rem; }\\r\\n.feature-card p { font-size: 1.1rem; line-height: 1.6; }\\r\\n\\r\\n\\/* ========== DARK MODE TOGGLE ========== *\\/\\r\\n.dark-toggle {\\r\\n  position: fixed;\\r\\n  bottom: 20px;\\r\\n  right: 20px;\\r\\n  background: #e94560;\\r\\n  color: white;\\r\\n  border: none;\\r\\n  border-radius: 50%;\\r\\n  width: 50px;\\r\\n  height: 50px;\\r\\n  font-size: 1.5rem;\\r\\n  cursor: pointer;\\r\\n  z-index: 1000;\\r\\n  box-shadow: 0 5px 15px rgba(233,69,96,0.5);\\r\\n  transition: 0.3s;\\r\\n}\\r\\n\\r\\n\\/* ========== ANIMATIONS ========== *\\/\\r\\n.fade-in {\\r\\n  opacity: 0;\\r\\n  transform: translateY(20px);\\r\\n  transition: 0.8s;\\r\\n}\\r\\n.fade-in.visible {\\r\\n  opacity: 1;\\r\\n  transform: translateY(0);\\r\\n}\\r\\n\\r\\n\\/* ========== RESPONSIVE ========== *\\/\\r\\n@media (max-width: 600px) {\\r\\n  .hero h1 { font-size: 2.2rem; }\\r\\n  .stats { gap: 1rem; }\\r\\n  .system-card { padding: 1.5rem; }\\r\\n}\\r\\n<\\/style>\\r\\n\\r\\n<!-- HTML STRUCTURE -->\\r\\n<div class=\\\"hero\\\">\\r\\n  <h1>Explore the Human Body<\\/h1>\\r\\n  <p>Interactive 3D models, comprehensive lessons, and AI\\u2011powered biology learning \\u2013 completely free.<\\/p>\\r\\n  <div class=\\\"search-container\\\">\\r\\n    <input type=\\\"text\\\" id=\\\"searchInput\\\" placeholder=\\\"Search organs, systems, diseases...\\\" \\r\\n           onkeypress=\\\"if(event.key===\'Enter\') window.location=\'\\/?s=\'+encodeURIComponent(this.value)\\\">\\r\\n  <\\/div>\\r\\n  <div class=\\\"hero-buttons\\\">\\r\\n    <a href=\\\"\\/3d-explorer\\\" class=\\\"btn btn-primary\\\">\\ud83e\\udec1 Explore 3D Body<\\/a>\\r\\n    <a href=\\\"\\/systems\\\" class=\\\"btn btn-secondary\\\">\\ud83d\\udcda Learn Biology<\\/a>\\r\\n  <\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<!-- Stats -->\\r\\n<div class=\\\"stats\\\">\\r\\n  <div class=\\\"stat-item\\\"><div class=\\\"stat-number\\\" id=\\\"counter1\\\">11<\\/div><div class=\\\"stat-label\\\">Body Systems<\\/div><\\/div>\\r\\n  <div class=\\\"stat-item\\\"><div class=\\\"stat-number\\\" id=\\\"counter2\\\">206<\\/div><div class=\\\"stat-label\\\">Bones<\\/div><\\/div>\\r\\n  <div class=\\\"stat-item\\\"><div class=\\\"stat-number\\\" id=\\\"counter3\\\">600+<\\/div><div class=\\\"stat-label\\\">Muscles<\\/div><\\/div>\\r\\n  <div class=\\\"stat-item\\\"><div class=\\\"stat-number\\\" id=\\\"counter4\\\">\\u221e<\\/div><div class=\\\"stat-label\\\">Learning Topics<\\/div><\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<!-- Body Systems Grid -->\\r\\n<div class=\\\"systems-section fade-in\\\">\\r\\n  <h2>\\ud83d\\udd2c Body Systems<\\/h2>\\r\\n  <div class=\\\"systems-grid\\\" id=\\\"systemsContainer\\\">\\r\\n    <!-- Generated by JavaScript -->\\r\\n  <\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<!-- Daily Features -->\\r\\n<div class=\\\"daily-features fade-in\\\">\\r\\n  <div class=\\\"feature-card\\\" id=\\\"organOfDay\\\">\\r\\n    <h3>\\ud83e\\udec0 Organ of the Day<\\/h3>\\r\\n    <p id=\\\"organName\\\">Loading...<\\/p>\\r\\n    <p id=\\\"organDesc\\\"><\\/p>\\r\\n  <\\/div>\\r\\n  <div class=\\\"feature-card\\\" id=\\\"factOfDay\\\">\\r\\n    <h3>\\ud83d\\udca1 Biology Fact<\\/h3>\\r\\n    <p id=\\\"factText\\\"><\\/p>\\r\\n  <\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<button class=\\\"dark-toggle\\\" onclick=\\\"toggleDarkMode()\\\" title=\\\"Toggle Dark\\/Light\\\">\\ud83c\\udf13<\\/button>\\r\\n\\r\\n<script>\\r\\n\\/\\/ ========== DATA ==========\\r\\nconst systems = [\\r\\n  { name: \\\"Skeletal System\\\", icon: \\\"\\ud83e\\uddb4\\\", desc: \\\"206 bones providing structure, protection, and movement.\\\", slug: \\\"skeletal-system\\\" },\\r\\n  { name: \\\"Muscular System\\\", icon: \\\"\\ud83d\\udcaa\\\", desc: \\\"Over 600 muscles enabling movement and stability.\\\", slug: \\\"muscular-system\\\" },\\r\\n  { name: \\\"Nervous System\\\", icon: \\\"\\ud83e\\udde0\\\", desc: \\\"Brain, spinal cord, and nerves controlling body functions.\\\", slug: \\\"nervous-system\\\" },\\r\\n  { name: \\\"Circulatory System\\\", icon: \\\"\\u2764\\ufe0f\\\", desc: \\\"Heart and blood vessels transporting nutrients and oxygen.\\\", slug: \\\"circulatory-system\\\" },\\r\\n  { name: \\\"Respiratory System\\\", icon: \\\"\\ud83e\\udec1\\\", desc: \\\"Lungs and airways for gas exchange.\\\", slug: \\\"respiratory-system\\\" },\\r\\n  { name: \\\"Digestive System\\\", icon: \\\"\\ud83c\\udf4e\\\", desc: \\\"Breaks down food into absorbable nutrients.\\\", slug: \\\"digestive-system\\\" },\\r\\n  { name: \\\"Endocrine System\\\", icon: \\\"\\ud83d\\udd2e\\\", desc: \\\"Hormone-producing glands regulating body processes.\\\", slug: \\\"endocrine-system\\\" },\\r\\n  { name: \\\"Immune System\\\", icon: \\\"\\ud83d\\udee1\\ufe0f\\\", desc: \\\"Defends against infections and diseases.\\\", slug: \\\"immune-system\\\" },\\r\\n  { name: \\\"Urinary System\\\", icon: \\\"\\ud83d\\udca7\\\", desc: \\\"Filters blood and removes waste as urine.\\\", slug: \\\"urinary-system\\\" },\\r\\n  { name: \\\"Reproductive System\\\", icon: \\\"\\ud83d\\udc76\\\", desc: \\\"Organs involved in reproduction.\\\", slug: \\\"reproductive-system\\\" },\\r\\n  { name: \\\"Integumentary System\\\", icon: \\\"\\u2728\\\", desc: \\\"Skin, hair, and nails protecting the body.\\\", slug: \\\"integumentary-system\\\" }\\r\\n];\\r\\n\\r\\nconst organs = [\\r\\n  { name: \\\"Heart\\\", fact: \\\"Your heart beats about 100,000 times a day.\\\", desc: \\\"The muscular pump of the circulatory system.\\\" },\\r\\n  { name: \\\"Brain\\\", fact: \\\"The brain uses 20% of the body\\u2019s oxygen.\\\", desc: \\\"Control centre of the nervous system.\\\" },\\r\\n  { name: \\\"Lungs\\\", fact: \\\"You breathe about 22,000 times per day.\\\", desc: \\\"Essential for gas exchange.\\\" },\\r\\n  { name: \\\"Liver\\\", fact: \\\"It can regenerate itself even if 75% removed.\\\", desc: \\\"The body\\u2019s chemical factory.\\\" },\\r\\n  { name: \\\"Kidneys\\\", fact: \\\"They filter about 150 litres of blood daily.\\\", desc: \\\"Maintains fluid and electrolyte balance.\\\" },\\r\\n  { name: \\\"Stomach\\\", fact: \\\"Stomach acid is strong enough to dissolve metal.\\\", desc: \\\"Breaks down food with acid and enzymes.\\\" }\\r\\n];\\r\\n\\r\\nconst facts = [\\r\\n  \\\"An adult has 206 bones, but a baby is born with ~270.\\\",\\r\\n  \\\"The strongest muscle in the body is the masseter (jaw muscle).\\\",\\r\\n  \\\"Your nose can remember 50,000 different scents.\\\",\\r\\n  \\\"The smallest bone is the stapes in the ear, just 2.5mm.\\\",\\r\\n  \\\"Red blood cells can travel through your entire body in 20 seconds.\\\",\\r\\n  \\\"Humans share 50% of their DNA with bananas.\\\"\\r\\n];\\r\\n\\r\\n\\/\\/ ========== POPULATE SYSTEMS ==========\\r\\nconst container = document.getElementById(\'systemsContainer\');\\r\\nsystems.forEach(sys => {\\r\\n  const card = document.createElement(\'a\');\\r\\n  card.className = \'system-card\';\\r\\n  card.href = \'\\/system\\/\' + sys.slug; \\/\\/ will be a real WordPress page later\\r\\n  card.innerHTML = `\\r\\n    <div class=\\\"system-icon\\\">${sys.icon}<\\/div>\\r\\n    <h3>${sys.name}<\\/h3>\\r\\n    <p>${sys.desc}<\\/p>\\r\\n  `;\\r\\n  container.appendChild(card);\\r\\n});\\r\\n\\r\\n\\/\\/ ========== DAILY RANDOMIZER ==========\\r\\nfunction getDailyIndex(max) {\\r\\n  const today = new Date().toISOString().slice(0,10).replace(\\/-\\/g,\'\');\\r\\n  return parseInt(today) % max;\\r\\n}\\r\\nconst organIndex = getDailyIndex(organs.length);\\r\\nconst factIndex = getDailyIndex(facts.length);\\r\\ndocument.getElementById(\'organName\').textContent = organs[organIndex].name;\\r\\ndocument.getElementById(\'organDesc\').textContent = organs[organIndex].fact;\\r\\ndocument.getElementById(\'factText\').textContent = facts[factIndex];\\r\\n\\r\\n\\/\\/ ========== DARK MODE ==========\\r\\nfunction toggleDarkMode() {\\r\\n  document.body.classList.toggle(\'dark-mode\');\\r\\n  localStorage.setItem(\'darkMode\', document.body.classList.contains(\'dark-mode\'));\\r\\n}\\r\\nif(localStorage.getItem(\'darkMode\') === \'true\') {\\r\\n  document.body.classList.add(\'dark-mode\');\\r\\n}\\r\\n\\r\\n\\/\\/ ========== SCROLL ANIMATION ==========\\r\\nconst observer = new IntersectionObserver((entries) => {\\r\\n  entries.forEach(entry => {\\r\\n    if(entry.isIntersecting) entry.target.classList.add(\'visible\');\\r\\n  });\\r\\n}, {threshold: 0.1});\\r\\ndocument.querySelectorAll(\'.fade-in\').forEach(el => observer.observe(el));\\r\\n\\r\\n\\/\\/ ========== STATS COUNTER (simple display, no animation needed) ==========\\r\\n\\/\\/ Already static, but you can add count-up on scroll later if desired\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),(1011,133,'footnotes',''),(1013,132,'_elementor_version','4.1.3'),(1014,132,'_elementor_global_class_usage_indexed','1'),(1015,132,'_elementor_global_class_usage_indexed_preview','1'),(1016,132,'_elementor_migrations_state_d2a1','4.1.3:6235a6c47f65a3aca2fc5a7c56ad64e4'),(1017,134,'footnotes',''),(1018,134,'_elementor_edit_mode','builder'),(1019,134,'_elementor_template_type','wp-page'),(1020,134,'_elementor_data',''),(1021,134,'_elementor_version','4.1.3'),(1022,134,'_elementor_global_class_usage_indexed','1'),(1023,134,'_elementor_global_class_usage_indexed_preview','1'),(1024,134,'_elementor_migrations_state_d2a1','4.1.3:6235a6c47f65a3aca2fc5a7c56ad64e4'),(1025,135,'footnotes',''),(1026,135,'_elementor_edit_mode','builder'),(1027,135,'_elementor_template_type','wp-page'),(1028,135,'_elementor_data',''),(1029,135,'_elementor_version','4.1.3'),(1030,135,'_elementor_global_class_usage_indexed','1'),(1031,135,'_elementor_global_class_usage_indexed_preview','1'),(1032,135,'_elementor_migrations_state_d2a1','4.1.3:6235a6c47f65a3aca2fc5a7c56ad64e4'),(1033,132,'_wp_page_template','default'),(1034,136,'footnotes',''),(1035,136,'_elementor_edit_mode','builder'),(1036,136,'_elementor_template_type','wp-page'),(1037,136,'_elementor_data','[{\"id\":\"4103f0d\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"22468aa\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!-- HUMAN BODY EXPL