ro::before {\n  content: \'\';\n  position: absolute;\n  top: -50%;\n  left: -50%;\n  width: 200%;\n  height: 200%;\n  background: radial-gradient(circle, rgba(255,255,255,0.1) 1px, transparent 1px);\n  background-size: 30px 30px;\n  animation: drift 20s linear infinite;\n}\n@keyframes drift {\n  from { transform: translate(0, 0); }\n  to { transform: translate(30px, 30px); }\n}\n.hero h1 {\n  font-size: clamp(2.5rem, 8vw, 4.5rem);\n  color: #fff;\n  text-shadow: 0 0 20px rgba(233,69,96,0.5);\n  margin-bottom: 1rem;\n  position: relative;\n  z-index: 1;\n}\n.hero p {\n  color: #ddd;\n  font-size: 1.2rem;\n  max-width: 700px;\n  margin: 0 auto 2rem;\n  position: relative;\n  z-index: 1;\n}\n.search-container {\n  width: 100%;\n  max-width: 500px;\n  position: relative;\n  z-index: 1;\n  margin-bottom: 2rem;\n}\n.search-container input {\n  width: 100%;\n  padding: 1rem 1.5rem;\n  border: none;\n  border-radius: 50px;\n  font-size: 1rem;\n  background: rgba(255,255,255,0.15);\n  backdrop-filter: blur(10px);\n  color: #fff;\n  outline: none;\n  border: 1px solid rgba(255,255,255,0.3);\n  transition: 0.3s;\n}\n.search-container input::placeholder { color: #ccc; }\n.search-container input:focus {\n  background: rgba(255,255,255,0.25);\n  border-color: #e94560;\n}\n.hero-buttons {\n  display: flex;\n  gap: 1rem;\n  flex-wrap: wrap;\n  justify-content: center;\n  position: relative;\n  z-index: 1;\n}\n.btn {\n  padding: 0.8rem 2rem;\n  border-radius: 50px;\n  font-weight: 600;\n  text-decoration: none;\n  transition: transform 0.3s, box-shadow 0.3s;\n  cursor: pointer;\n  border: none;\n  font-size: 1rem;\n}\n.btn-primary {\n  background: #e94560;\n  color: #fff;\n}\n.btn-primary:hover { transform: translateY(-3px); box-shadow: 0 10px 20px rgba(233,69,96,0.4); }\n.btn-secondary {\n  background: transparent;\n  border: 2px solid #fff;\n  color: #fff;\n}\n.btn-secondary:hover { background: #fff; color: #1a1a2e; }\n/* ========== STATS SECTION ========== */\n.stats {\n  display: flex;\n  justify-content: center;\n  gap: 2rem;\n  flex-wrap: wrap;\n  padding: 2rem 1rem;\n  background: #16213e;\n}\n.stat-item {\n  text-align: center;\n  color: #fff;\n}\n.stat-number {\n  font-size: 2.5rem;\n  font-weight: 700;\n  color: #e94560;\n}\n.stat-label { font-size: 1rem; color: #ccc; }\n/* ========== SYSTEMS GRID ========== */\n.systems-section {\n  padding: 4rem 2rem;\n  background: inherit;\n}\n.systems-section h2 {\n  text-align: center;\n  margin-bottom: 2rem;\n  font-size: 2rem;\n  color: inherit;\n}\n.systems-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n  gap: 1.5rem;\n  max-width: 1200px;\n  margin: 0 auto;\n}\n.system-card {\n  background: rgba(255,255,255,0.08);\n  backdrop-filter: blur(12px);\n  border-radius: 20px;\n  padding: 2rem 1.5rem;\n  text-align: center;\n  border: 1px solid rgba(255,255,255,0.2);\n  transition: transform 0.3s, box-shadow 0.3s;\n  cursor: pointer;\n  color: inherit;\n  text-decoration: none;\n  display: block;\n}\n.system-card:hover {\n  transform: translateY(-8px);\n  box-shadow: 0 20px 40px rgba(0,0,0,0.3);\n}\n.system-icon {\n  font-size: 3rem;\n  margin-bottom: 1rem;\n}\n.system-card h3 {\n  font-size: 1.3rem;\n  margin-bottom: 0.5rem;\n}\n.system-card p {\n  font-size: 0.9rem;\n  opacity: 0.8;\n}\n/* ========== DAILY FEATURES ========== */\n.daily-features {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 2rem;\n  justify-content: center;\n  padding: 3rem 1rem;\n  max-width: 1200px;\n  margin: 0 auto;\n}\n.feature-card {\n  flex: 1 1 300px;\n  background: rgba(255,255,255,0.1);\n  backdrop-filter: blur(10px);\n  border-radius: 20px;\n  padding: 2rem;\n  border: 1px solid rgba(255,255,255,0.2);\n}\n.feature-card h3 { margin-bottom: 1rem; display: flex; align-items: center; gap: 0.5rem; }\n.feature-card p { font-size: 1.1rem; line-height: 1.6; }\n/* ========== DARK MODE TOGGLE ========== */\n.dark-toggle {\n  position: fixed;\n  bottom: 20px;\n  right: 20px;\n  background: #e94560;\n  color: white;\n  border: none;\n  border-radius: 50%;\n  width: 50px;\n  height: 50px;\n  font-size: 1.5rem;\n  cursor: pointer;\n  z-index: 1000;\n  box-shadow: 0 5px 15px rgba(233,69,96,0.5);\n  transition: 0.3s;\n}\n/* ========== ANIMATIONS ========== */\n.fade-in {\n  opacity: 0;\n  transform: translateY(20px);\n  transition: 0.8s;\n}\n.fade-in.visible {\n  opacity: 1;\n  transform: translateY(0);\n}\n/* ========== RESPONSIVE ========== */\n@media (max-width: 600px) {\n  .hero h1 { font-size: 2.2rem; }\n  .stats { gap: 1rem; }\n  .system-card { padding: 1.5rem; }\n}\n</style>\n<!-- HTML STRUCTURE -->\n  <h1>Explore the Human Body</h1>\n  <p>Interactive 3D models, comprehensive lessons, and AIΓÇæpowered biology learning ΓÇô completely free.</p>\n    <input type=\"text\" id=\"searchInput\" placeholder=\"Search organs, systems, diseases...\" \n           onkeypress=\"if(event.key===\'Enter\') window.location=\'/?s=\'+encodeURIComponent(this.value)\">\n    <a href=\"/3d-explorer\">≡ƒ½ü Explore 3D Body</a>\n    <a href=\"/systems\">≡ƒôÜ Learn Biology</a>\n<!-- Stats -->\n  11Body Systems\n  206Bones\n  600+Muscles\n  Γê₧Learning Topics\n<!-- Body Systems Grid -->\n  <h2>≡ƒö¼ Body Systems</h2>\n    <!-- Generated by JavaScript -->\n<!-- Daily Features -->\n    <h3>≡ƒ½Ç Organ of the Day</h3>\n    <p id=\"organName\">Loading...</p>\n    <p id=\"organDesc\"></p>\n    <h3>≡ƒÆí Biology Fact</h3>\n    <p id=\"factText\"></p>\n<button onclick=\"toggleDarkMode()\" title=\"Toggle Dark/Light\">≡ƒîô</button>','Elementor #132','','inherit','closed','closed','','132-revision-v1','','','2026-06-14 18:43:54','2026-06-14 18:43:54','',132,'http://localhost/biology/?p=136',0,'revision','',0),(138,1,'2026-06-14 18:47:32','2026-06-14 18:47:32','','3D Explorer','','inherit','closed','closed','','137-revision-v1','','','2026-06-14 18:47:32','2026-06-14 18:47:32','',137,'http://localhost/biology/?p=138',0,'revision','',0),(139,1,'2026-06-15 19:29:45','2026-06-15 19:29:45','<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>3D Human Body Explorer - All 6 Systems</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n        body {\n            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\n            background: linear-gradient(135deg, #050b1a 0%, #0a1628 100%);\n            min-height: 100vh;\n        }\n        .header {\n            text-align: center;\n            padding: 30px 20px 20px;\n        }\n        .header h1 {\n            color: white;\n            font-size: 2rem;\n            margin-bottom: 10px;\n        }\n        .header p {\n            color: #88aaff;\n            font-size: 1rem;\n        }\n        .system-buttons {\n            display: flex;\n            flex-wrap: wrap;\n            justify-content: center;\n            gap: 12px;\n            padding: 20px;\n        }\n        .sys-btn {\n            background: rgba(20, 30, 50, 0.9);\n            border: none;\n            border-left: 3px solid;\n            border-radius: 40px;\n            color: white;\n            cursor: pointer;\n            font-family: monospace;\n            font-size: 14px;\n            font-weight: 600;\n            padding: 10px 20px;\n            transition: all 0.2s;\n        }\n        .sys-btn:hover {\n            transform: translateY(-2px);\n            background: #0f3460;\n        }\n        .sys-btn.active {\n            background: #0f3460;\n            box-shadow: 0 0 15px rgba(0,160,255,0.5);\n        }\n        .viewer-container {\n            width: 95%;\n            max-width: 1300px;\n            margin: 0 auto;\n            background: #000;\n            border-radius: 20px;\n            overflow: hidden;\n            box-shadow: 0 0 40px rgba(0,160,255,0.2);\n        }\n        .viewer-container iframe {\n            width: 100%;\n            height: 600px;\n            border: none;\n        }\n        .instructions {\n            text-align: center;\n            padding: 20px;\n            color: #88aaff;\n            font-size: 12px;\n        }\n        .info-panel {\n            width: 95%;\n            max-width: 1300px;\n            margin: 20px auto;\n            background: rgba(0,0,0,0.5);\n            border-radius: 15px;\n            padding: 20px;\n            backdrop-filter: blur(10px);\n        }\n        .info-panel h3 {\n            color: #00ffcc;\n            margin-bottom: 10px;\n        }\n        .info-panel p {\n            color: #ccc;\n            line-height: 1.6;\n        }\n        @media (max-width: 768px) {\n            .sys-btn { padding: 6px 12px; font-size: 10px; }\n            .viewer-container iframe { height: 400px; }\n            .header h1 { font-size: 1.5rem; }\n        }\n    </style>\n</head>\n<body>\n    <h1>≡ƒª┤ Interactive 3D Human Anatomy Explorer</h1>\n    <p>Click any system below to explore in full 3D | Drag to rotate | Scroll to zoom</p>\n    <button onclick=\"loadModel(\'skeletal\')\" id=\"btn-skeletal\" style=\"border-left-color: #f5f5dc;\">≡ƒª┤ SKELETAL</button>\n    <button onclick=\"loadModel(\'circulatory\')\" id=\"btn-circulatory\" style=\"border-left-color: #ff3366;\">Γ¥ñ∩╕Å CIRCULATORY</button>\n    <button onclick=\"loadModel(\'respiratory\')\" id=\"btn-respiratory\" style=\"border-left-color: #44aaff;\">≡ƒ½ü RESPIRATORY</button>\n    <button onclick=\"loadModel(\'nervous\')\" id=\"btn-nervous\" style=\"border-left-color: #88ff88;\">ΓÜí NERVOUS</button>\n    <button onclick=\"loadModel(\'muscular\')\" id=\"btn-muscular\" style=\"border-left-color: #ff88aa;\">≡ƒÆ¬ MUSCULAR</button>\n    <button onclick=\"loadModel(\'digestive\')\" id=\"btn-digestive\" style=\"border-left-color: #ffaa44;\">≡ƒì╜∩╕Å DIGESTIVE</button>\n    <iframe id=\"modelFrame\" src=\"https://sketchfab.com/models/b2b679065af341acbf05665334960e5c/embed?autospin=1&autostart=1&preload=1&ui_controls=1&ui_infos=0&ui_stop=0&ui_annotations=0&ui_inspector=0&ui_help=0&ui_settings=0&ui_vr=0&ui_ar=0&ui_fullscreen=1\"></iframe>\n    <h3>≡ƒª┤ Skeletal System</h3>\n    <p>The skeletal system consists of 206 bones that provide structure, protect vital organs, enable movement, and produce blood cells. It includes the skull, spine, ribcage, and limbs.</p>\n    ≡ƒû▒∩╕Å DRAG to rotate the 3D model | ≡ƒôî SCROLL to zoom in/out | ≡ƒû▒∩╕Å CLICK buttons to switch body systems\n</body>\n</html>','3D Explorer','','inherit','closed','closed','','137-revision-v1','','','2026-06-15 19:29:45','2026-06-15 19:29:45','',137,'http://localhost/biology/?p=139',0,'revision','',0),(140,1,'2026-06-15 19:29:55','2026-06-15 19:29:55','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost/biology.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','inherit','closed','closed','','3-revision-v1','','','2026-06-15 19:29:55','2026-06-15 19:29:55','',3,'http://localhost/biology/?p=140',0,'revision','',0),(142,1,'2026-06-15 19:36:21','2026-06-15 19:36:21','<!-- Hero Section -->\n        <h1 style=\"color: white; font-size: 3rem; margin: 0;\">≡ƒö¼ Human Body Explorer</h1>\n        <p style=\"color: #88aaff; font-size: 1.2rem; margin: 20px 0;\">Free Interactive Biology Learning Platform</p>\n        <!-- SEARCH BAR - Custom Search (No Plugin Needed) -->\n                <input type=\"text\" id=\"searchInput\" placeholder=\"≡ƒöì Search organs, systems, or topics... (heart, brain, lungs, bones)\" \n                       style=\"flex: 1; padding: 15px 20px; border: none; background: transparent; color: white; font-size: 1rem; outline: none;\">\n                <button onclick=\"performSearch()\" style=\"background: #00aaff; border: none; border-radius: 50px; padding: 0 25px; color: white; font-weight: bold; cursor: pointer;\">Search</button>\n            <a href=\"/biology/3d-explorer\" style=\"background: #00aaff; color: white; padding: 12px 30px; border-radius: 40px; text-decoration: none; font-weight: bold;\">≡ƒÜÇ Explore 3D Body</a>\n            <a href=\"/biology/ai-tutor\" style=\"background: transparent; border: 2px solid #00aaff; color: #00aaff; padding: 12px 30px; border-radius: 40px; text-decoration: none; font-weight: bold;\">≡ƒñû Ask AI Tutor</a>\n    <!-- Statistics -->\n            11\n            Body Systems\n            206\n            Bones\n            600+\n            Muscles\n 